function lastStep(steps) {
  if (steps.length === 0) return null;
  return steps[steps.length - 1];
}

function stepsAfter(steps, name) {
  const i = steps.indexOf(name);
  if (i === -1) return [];
  return steps.slice(i + 1);
}

function withRollback(steps, healthy) {
  if (healthy) return [...steps];
  return [...steps, "rollback"];
}

function isComplete(required, actual) {
  return required.every((step) => actual.includes(step));
}

function firstMissing(required, actual) {
  for (const step of required) {
    if (!actual.includes(step)) return step;
  }
  return null;
}

function inOrder(required, actual) {
  let from = 0;
  for (const step of required) {
    const i = actual.indexOf(step, from);
    if (i === -1) return false;
    from = i + 1;
  }
  return true;
}

function retryHealthCheck(check, attempts) {
  for (let n = 1; n <= attempts; n++) {
    if (check(n)) return n;
  }
  return 0;
}

function gatedDeploy(current, next, healthy) {
  const actions = [
    `extract:${next}`,
    `install-deps:${next}`,
    `run-migrations:${next}`,
    `health-check:${next}`,
  ];
  if (healthy) {
    actions.push(`switch-symlink:${current}->${next}`);
    actions.push("restart-service");
  } else {
    actions.push(`keep-live:${current}`);
  }
  return actions;
}
